test('S-001 · View their current daily and per-transaction payment limits meets latency budget', async ({ request }) => {
  const samples: number[] = [];
  for (let i = 0; i < 20; i++) {
    const t0 = Date.now();
    const res = await request.get('/view_their_current_daily_and_per_transaction_payment_limits');
    samples.push(Date.now() - t0);
    expect(res.ok()).toBeTruthy();
  }
  samples.sort((a, b) => a - b);
  const p95 = samples[Math.floor(samples.length * 0.95) - 1];
  expect(p95).toBeLessThan(2000);
});

